cssRules:
.code-box {
  position: relative;
  background: #090a0f;
  border: 1px solid #1f2430;
  border-radius: 6px;
  padding: 12px 48px 12px 14px;
  overflow-x: auto;
}
.code-box pre {
  margin: 0;
  font-family: 'JetBrains Mono', Consolas, monospace;
  font-size: 12px;
  color: #e6edf3;
}
.copy-btn {
  position: absolute;
  right: 8px;
  top: 8px;
  font-size: 11px;
  padding: 3px 8px;
  border-radius: 4px;
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid rgba(255, 255, 255, 0.15);
  color: #d1d5db;
  cursor: pointer;
  transition: all 0.15s;
}
.copy-btn:hover {
  background: rgba(255, 255, 255, 0.16);
  color: #ffffff;
}
